  const ENEMY_TYPES = [
    { type: "grunt",    baseHp: 60,  speed: 10, bounty: 4, leak: 1, air: 0, firstWave: 1, weight: 10 },
    { type: "runner",   baseHp: 40,  speed: 20, bounty: 4, leak: 1, air: 0, firstWave: 2, weight: 4  },
    { type: "wisp",     baseHp: 50,  speed: 12, bounty: 6, leak: 2, air: 1, firstWave: 3, weight: 3  },
    { type: "brute",    baseHp: 150, speed: 6,  bounty: 9, leak: 3, air: 0, firstWave: 4, weight: 3  },
    { type: "splitter", baseHp: 90,  speed: 8,  bounty: 6, leak: 2, air: 0, firstWave: 6, weight: 2  },
    { type: "mender",   baseHp: 70,  speed: 8,  bounty: 7, leak: 2, air: 0, firstWave: 8, weight: 1  }
  ];
  const rng = mulberry32(7);
  for (let w = 1; w <= 12; w++) {
    const count = 4 + Math.floor(3 * w / 5);
    const avail = ENEMY_TYPES.filter(e => e.firstWave <= w);
    const tw = avail.reduce((s, e) => s + e.weight, 0);
    const res = [];
    for (let i = 0; i < count; i++) {
      let r = rng() % tw;
      for (const a of avail) {
        if (r < a.weight) { res.push(a.type); break; }
        r -= a.weight;
      }
    }
    print("Wave", w, "(tick", 20 + 40*(w-1), "):", JSON.stringify(res));
  }
}
traceB();
